// Kill-switch: an earlier deployment registered a service worker from this
// URL. Browsers that still have it will fetch this file on their next visit,
// install it, and it immediately unregisters itself and reloads open pages
// so they get the real site.
self.addEventListener('install', function () { self.skipWaiting(); });
self.addEventListener('activate', function (event) {
  event.waitUntil(
    self.registration.unregister()
      .then(function () { return self.clients.matchAll({ type: 'window' }); })
      .then(function (clients) {
        clients.forEach(function (client) { client.navigate(client.url); });
      })
  );
});
